/*
 * THE ONE OWNER OF MESSAGE MAIL (DBU-07). Nothing else mails about messages.
 *
 *   request { learnerId, to: 'coach' | 'learner' }  sendMessage / replyAsCoach, right after saving
 *   request { all: true }                            mailMessages, the every-minute flush
 *
 * WHAT. Every message saved with mailPending: true, grouped per learner and direction: one email
 * carries all of a learner's waiting messages to the coach, or all the coach's waiting replies to her.
 * WHEN. At once, unless an email already went the same way for this learner in the last HOLD
 * (5 minutes; the secret mailHoldSeconds, which only tools/check-mail.mjs lowers). Then the messages
 * wait, and the flush sends them together when the 5 minutes are up. So the first message reaches
 * the coach within a minute, and a burst of messages is one more email, not a stream.
 * WHO. To the coach: Setting coachEmail, else DEFAULT_COACH (a placeholder: set the real address in
 * Settings). To the learner: her account address,
 * unless she turned message emails off (emailOptOutAt): then nothing is sent and the messages are
 * marked dealt with, so they are never mailed later.
 * A MAIL NEVER FAILS A WRITE: this always answers done. The messages are claimed (mailPending false)
 * before the send and given back if it fails, so the flush tries again. Logs carry ids and counts,
 * never an address or a message.
 */
if (Inputs.request !== undefined && Inputs.request !== null) {
  (async () => {
    const r = Inputs.request || {};
    let sent = 0;
    let held = 0;
    try {
      const R = Noodl.Records;
      const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
      const secret = (name) => {
        const s = globalThis._noodl_get_secret ? globalThis._noodl_get_secret(name) : null;
        return s && s.found ? String(s.value) : '';
      };
      const send = typeof globalThis._noodl_send_email === 'function' ? globalThis._noodl_send_email : null;
      const appUrl = secret('appUrl').replace(/\/+$/, '');
      if (!send || !appUrl) {
        console.error('[dbu:Message mail] no mailer or no appUrl secret (tools/setup-signin.mjs): nothing sent');
        Outputs.sent = 0;
        Outputs.held = 0;
        Outputs.done();
        return;
      }
      const holdSetting = Number(secret('mailHoldSeconds'));
      const HOLD_MS = (Number.isFinite(holdSetting) && secret('mailHoldSeconds') !== '' ? holdSetting : 300) * 1000;
      const DEFAULT_COACH = 'coach@example.com';
      const key = secret('unsubscribeKey');

      const pending = r.all === true
        ? await q('Message', { mailPending: { equalTo: true } })
        : (await q('Message', { learner: { equalTo: String(r.learnerId || '') } })).filter((m) => m.mailPending === true);
      const groups = new Map();
      for (const m of pending) {
        const to = m.author === m.learner ? 'coach' : 'learner';
        if (r.all !== true && r.to && r.to !== to) continue;
        const k = m.learner + '|' + to;
        if (!groups.has(k)) groups.set(k, { learner: m.learner, to, list: [] });
        groups.get(k).list.push(m);
      }

      const settings = await q('Setting', { key: { equalTo: 'coachEmail' } });
      const coachAddress = (settings[0] && String(settings[0].value || '').trim()) || DEFAULT_COACH;
      const hex = (buf) => Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, '0')).join('');
      const unsubscribeFor = async (userId) => {
        if (!key) return '';
        const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
        const sig = hex(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode('dbu-unsubscribe:v1:' + userId)));
        return appUrl + '/unsubscribe?u=' + encodeURIComponent(userId) + '&s=' + sig;
      };

      for (const g of groups.values()) {
        const tag = '[dbu:Message mail] to=' + g.to + ' learner=' + g.learner;
        const everything = await q('Message', { learner: { equalTo: g.learner } });
        const sameWay = everything.filter((m) => (m.author === m.learner) === (g.to === 'coach'));
        const last = sameWay.map((m) => m.mailedAt).filter(Boolean).sort().pop();
        if (last && Date.now() - Date.parse(last) < HOLD_MS) {
          held += g.list.length;
          continue;
        }
        const users = await q('_User', { objectId: { equalTo: g.learner } });
        const learner = users[0];
        if (!learner) {
          console.error(tag + ' no such account: not sent');
          continue;
        }
        const list = g.list.slice().sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
        const stamp = new Date().toISOString();
        const claim = (pendingNow) => Promise.all(list.map((m) =>
          R.save(m.objectId, pendingNow ? { mailPending: true, mailedAt: null } : { mailPending: false, mailedAt: stamp }, { className: 'Message' })));

        const address = typeof learner.email === 'string' && learner.email.includes('@') ? learner.email : '';
        if (g.to === 'learner' && (learner.emailOptOutAt || !address)) {
          await claim(false);
          console.log(tag + ' not sent: the learner turned message emails off (' + list.length + ' message(s))');
          continue;
        }

        const stepIds = [...new Set(list.map((m) => m.step).filter(Boolean))];
        const steps = stepIds.length ? await q('Step', { objectId: { containedIn: stepIds } }) : [];
        const titleOf = (id) => { const s = steps.find((x) => x.objectId === id); return s ? String(s.title || '') : ''; };
        const learnerName = String(learner.name || learner.email || 'A learner');
        const learnerFirst = learnerName.split(' ')[0];
        const lines = [];
        for (const m of list) {
          const title = m.step ? titleOf(m.step) : '';
          if (title) lines.push((g.to === 'coach' ? 'About the homework "' : 'About your homework "') + title + '":');
          if (String(m.body || '').trim()) lines.push(String(m.body).trim());
          const att = (Array.isArray(m.attachments) ? m.attachments : []).map((a) => a && a.name).filter(Boolean);
          if (att.length) lines.push('Attached: ' + att.join(', '));
          lines.push('');
        }

        let to, subject, text;
        if (g.to === 'coach') {
          to = coachAddress;
          subject = list.length === 1 ? learnerName + ' sent you a message' : learnerName + ' sent you ' + list.length + ' messages';
          text = [
            learnerName + (list.length === 1 ? ' wrote:' : ' wrote ' + list.length + ' messages:'),
            '',
            ...lines,
            'Reply to ' + learnerFirst + ': ' + appUrl + '/coach/plan?learner=' + encodeURIComponent(g.learner),
            '',
            '--',
            'Replies to this email are not read. Answer on Digital Bricks University, and ' + learnerFirst + ' will see it there.'
          ].join('\n');
        } else {
          const authors = [...new Set(list.map((m) => m.author))];
          const coaches = await q('_User', { objectId: { containedIn: authors } });
          const coachFirst = String((coaches[0] && coaches[0].name) || 'Your coach').split(' ')[0];
          const oneStep = stepIds.length === 1 && list.every((m) => m.step === stepIds[0]);
          const link = oneStep ? appUrl + '/homework?step=' + encodeURIComponent(stepIds[0]) : appUrl + '/messages';
          const unsubscribe = await unsubscribeFor(learner.objectId);
          if (!unsubscribe) console.error(tag + ' no unsubscribeKey secret (tools/setup-signin.mjs): the footer has no link');
          to = address;
          subject = coachFirst + ' replied';
          text = [
            'Hello ' + learnerFirst + ',',
            '',
            coachFirst + (list.length === 1 ? ' replied:' : ' sent you ' + list.length + ' messages:'),
            '',
            ...lines,
            'Read it and answer: ' + link,
            '',
            '--',
            'Replies to this email are not read. Answer on Digital Bricks University, and ' + coachFirst + ' will see it there.',
            unsubscribe ? 'Stop these emails: ' + unsubscribe : 'You can stop these emails on your Messages page.',
            'Your sign-in emails are not affected.'
          ].join('\n');
        }

        await claim(false);
        let ok = false;
        let why = '';
        try {
          const res = await send({ to, subject, text });
          ok = !!(res && res.success);
          why = ok ? '' : String((res && res.error) || 'no answer');
        } catch (e) {
          why = String((e && e.message) || e);
        }
        if (ok) sent += 1;
        else {
          await claim(true);
          console.error(tag + ' send failed, left for the next flush: ' + why.slice(0, 160).replace(/[^\s]+@[^\s]+/g, '<address>'));
        }
      }
      if (sent || held) console.log('[dbu:Message mail] sent=' + sent + ' held=' + held);
    } catch (e) {
      console.error('[dbu:Message mail] ' + String((e && e.message) || e));
    }
    Outputs.sent = sent;
    Outputs.held = held;
    Outputs.done();
  })();
}
